import React, { useState } from 'react';

export default function LoginModal({ isOpen, onClose, onLoginSuccess }) {
  const [activeLoginType, setActiveLoginType] = useState('customer'); // 'customer' | 'admin'

  // Passenger form
  const [passengerName, setPassengerName] = useState('');
  const [passengerPhone, setPassengerPhone] = useState('');

  // Admin form
  const [adminEmail, setAdminEmail] = useState('admin@diyataxi.com');
  const [adminPassword, setAdminPassword] = useState('admin123');
  const [error, setError] = useState('');

  if (!isOpen) return null;

  const handleCustomerSubmit = (e) => {
    e.preventDefault();
    if (!passengerName.trim()) {
      setError('Please enter your name.');
      return;
    }
    setError('');
    onLoginSuccess({
      role: 'customer',
      name: passengerName.trim(),
      phone: passengerPhone.trim() || '+91 98765 43210'
    });
    onClose();
  };

  const handleAdminSubmit = (e) => {
    e.preventDefault();
    if (adminEmail.trim().toLowerCase() === 'admin@diyataxi.com' && adminPassword === 'admin123') {
      setError('');
      onLoginSuccess({
        role: 'admin',
        name: 'Operations Admin',
        email: 'admin@diyataxi.com'
      });
      onClose();
    } else {
      setError('Invalid Admin credentials. (Use: admin@diyataxi.com / admin123)');
    }
  };

  const handleQuickAdminLogin = () => {
    setError('');
    onLoginSuccess({
      role: 'admin',
      name: 'Operations Admin',
      email: 'admin@diyataxi.com'
    });
    onClose();
  };

  return (
    <div className="modal-overlay open">
      <div className="modal-card" style={{ maxWidth: '440px' }}>
        <div className="modal-header">
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <div style={{
              width: '36px',
              height: '36px',
              borderRadius: '10px',
              background: 'linear-gradient(135deg, #f59e0b, #d97706)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: '18px',
              color: '#080c14'
            }}>
              {activeLoginType === 'admin' ? '🔐' : '👤'}
            </div>
            <div>
              <h3 style={{ fontSize: '18px', fontWeight: 700 }}>
                {activeLoginType === 'admin' ? 'Admin Portal Login' : 'Passenger Login'}
              </h3>
              <div style={{ fontSize: '12px', color: 'var(--text-muted)' }}>
                {activeLoginType === 'admin' ? 'Authorized personnel access' : 'Enter your name to start booking'}
              </div>
            </div>
          </div>
          <button className="modal-close-btn" onClick={onClose}>&times;</button>
        </div>

        {/* Tab switch between Passenger & Admin */}
        <div style={{
          display: 'flex',
          background: 'rgba(13, 19, 34, 0.8)',
          padding: '4px',
          borderRadius: '10px',
          margin: '16px 24px 0 24px',
          gap: '4px'
        }}>
          <button
            type="button"
            style={{
              flex: 1,
              padding: '8px',
              borderRadius: '8px',
              border: 'none',
              cursor: 'pointer',
              fontWeight: 700,
              fontSize: '13px',
              background: activeLoginType === 'customer' ? 'var(--primary)' : 'transparent',
              color: activeLoginType === 'customer' ? '#080c14' : 'var(--text-secondary)'
            }}
            onClick={() => { setActiveLoginType('customer'); setError(''); }}
          >
            👤 Passenger Login
          </button>
          <button
            type="button"
            style={{
              flex: 1,
              padding: '8px',
              borderRadius: '8px',
              border: 'none',
              cursor: 'pointer',
              fontWeight: 700,
              fontSize: '13px',
              background: activeLoginType === 'admin' ? 'var(--primary)' : 'transparent',
              color: activeLoginType === 'admin' ? '#080c14' : 'var(--text-secondary)'
            }}
            onClick={() => { setActiveLoginType('admin'); setError(''); }}
          >
            🔐 Admin Login
          </button>
        </div>

        <div className="modal-body">
          {error && (
            <div style={{
              background: 'rgba(239, 68, 68, 0.15)',
              border: '1px solid rgba(239, 68, 68, 0.4)',
              color: '#f87171',
              padding: '10px 14px',
              borderRadius: '8px',
              fontSize: '13px',
              marginBottom: '16px'
            }}>
              ⚠️ {error}
            </div>
          )}

          {activeLoginType === 'customer' ? (
            /* Passenger Login Form */
            <form onSubmit={handleCustomerSubmit}>
              <div style={{ marginBottom: '16px' }}>
                <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: 'var(--text-secondary)', marginBottom: '6px', textTransform: 'uppercase' }}>
                  Your Name <span style={{ color: 'var(--primary)' }}>*</span>
                </label>
                <input
                  type="text"
                  className="input-control"
                  style={{ width: '100%' }}
                  placeholder="e.g. Pavithra"
                  value={passengerName}
                  onChange={(e) => setPassengerName(e.target.value)}
                  autoFocus
                  required
                />
              </div>

              <div style={{ marginBottom: '22px' }}>
                <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: 'var(--text-secondary)', marginBottom: '6px', textTransform: 'uppercase' }}>
                  Mobile Number (Optional)
                </label>
                <input
                  type="tel"
                  className="input-control"
                  style={{ width: '100%' }}
                  placeholder="+91 98765 43210"
                  value={passengerPhone}
                  onChange={(e) => setPassengerPhone(e.target.value)}
                />
              </div>

              <button type="submit" className="btn btn-primary" style={{ width: '100%', padding: '12px', fontSize: '15px' }}>
                Continue as Passenger 🚖
              </button>
            </form>
          ) : (
            /* Admin Login Form */
            <form onSubmit={handleAdminSubmit}>
              <div style={{ marginBottom: '16px' }}>
                <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: 'var(--text-secondary)', marginBottom: '6px', textTransform: 'uppercase' }}>
                  Admin Email
                </label>
                <input
                  type="email"
                  className="input-control"
                  style={{ width: '100%' }}
                  value={adminEmail}
                  onChange={(e) => setAdminEmail(e.target.value)}
                  placeholder="admin@diyataxi.com"
                  required
                />
              </div>

              <div style={{ marginBottom: '22px' }}>
                <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: 'var(--text-secondary)', marginBottom: '6px', textTransform: 'uppercase' }}>
                  Password
                </label>
                <input
                  type="password"
                  className="input-control"
                  style={{ width: '100%' }}
                  value={adminPassword}
                  onChange={(e) => setAdminPassword(e.target.value)}
                  placeholder="••••••••"
                  required
                />
              </div>

              <button type="submit" className="btn btn-primary" style={{ width: '100%', padding: '12px', fontSize: '15px', marginBottom: '12px' }}>
                Login to Admin Dashboard 🚀
              </button>

              <button
                type="button"
                className="btn btn-secondary"
                onClick={handleQuickAdminLogin}
                style={{ width: '100%', padding: '10px', fontSize: '13px' }}
              >
                ⚡ 1-Click Quick Demo Admin Login
              </button>

              <div style={{ marginTop: '16px', padding: '10px', background: 'rgba(255,255,255,0.03)', borderRadius: '8px', fontSize: '12px', color: 'var(--text-muted)' }}>
                <span style={{ color: 'var(--primary)', fontWeight: 600 }}>Demo Admin:</span> admin@diyataxi.com &bull; <span style={{ color: 'var(--primary)', fontWeight: 600 }}>Pass:</span> admin123
              </div>
            </form>
          )}
        </div>
      </div>
    </div>
  );
}
